Color TraceWhitted(
    Scene scene,
    Ray ray,
    uint32_t depth)
{
    if (depth > MaxDepth)
        return black;

    hit = scene.Intersect(ray);

    if (!hit)
        return environment;

    if (emissive)
        return emission;

    if (mirror)
        return Trace(reflectionRay);

    if (glass)
        return
            F * Trace(reflectionRay)
            +
            (1-F) * Trace(refractionRay);

    return DirectLighting(hit);
}

